Object.assign(SNIP,{});PRESET_NOTES["l53"]={"Ví dụ: DFS đệ quy": "Thứ tự thăm 1 2 4 3 5: từ 1 đi sâu sang 2, rồi 4, rồi 3 (ngõ cụt vì 1 đã thăm), quay lại 4 và đi tiếp 5. Đỉnh 6, 7 không tới được từ 1. Cạnh đậm là cây DFS.", "Ví dụ: DFS bằng ngăn xếp tự quản lý": "Không có đệ quy nên không lo tràn ngăn xếp lời gọi. Đẩy các đỉnh kề theo thứ tự ngược để đỉnh kề đầu tiên được lấy ra trước: thứ tự thăm 1 2 4 3 5, giống bản đệ quy.", "Ví dụ: Đếm thành phần liên thông": "3 thành phần: {1, 2, 3}, {4, 5, 6, 7}, {8}. Đỉnh 8 không có cạnh nào vẫn là một thành phần riêng. Số dưới mỗi đỉnh là nhãn comp.", "Ví dụ: Đếm hòn đảo bằng tô loang": "4 hòn đảo, mỗi hòn một nhãn trong bảng. Hàm loang tự kiểm tra biên và điều kiện ở đầu, nên lời gọi gọn: cứ gọi cả 4 hướng.", "Lỗi: đệ quy quá sâu": "Đồ thị là một đường dài nên dfs lồng nhau 6000 tầng: trình mô phỏng dừng vì tràn ngăn xếp lời gọi (máy thật chịu được sâu hơn, nhưng với 10⁶ đỉnh cũng sập). Đồ thị có thể sâu thì dùng DFS bằng ngăn xếp tự quản lý, hoặc BFS."};EX_HINTS["l53"]=[["Duyệt u = 1 … n; gặp đỉnh chưa thăm thì đó là một cụm mới: tăng bộ đếm, rồi DFS (hoặc BFS) từ u.", "Cho dfs trả về số đỉnh nó thăm (1 + tổng của các lời gọi con) để biết kích cỡ cụm.", "Đồ thị có thể là một đường rất dài: trên máy thật nên dùng ngăn xếp tự quản lý hoặc BFS cho chắc."], ["Duyệt mọi ô; gặp ô đất chưa thăm thì tăng số đảo và tô loang (DFS hoặc BFS) toàn bộ đảo đó.", "Chỉ đi sang ô chung cạnh (4 hướng), không đi chéo.", "Một đảo hình con rắn có thể dài 10^6 ô: dùng ngăn xếp tự quản lý thay cho đệ quy."], ["Đồ thị có hướng: chỉ thêm adj[u].push_back(v).", "Duyệt (DFS hoặc BFS) từ đỉnh 1; mọi đỉnh được thăm là người biết tin.", "Không cần sắp xếp: in các u từ 1 tới n mà tham[u] đúng là đã tăng dần."]];
/* ===================== BÀI 53 · DFS và thành phần liên thông ===================== */
/* Bài 53 · DFS và thành phần liên thông
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR53=[{label:"Ví dụ: DFS đệ quy",input:"7 7\n1 2\n1 3\n2 4\n3 4\n4 5\n6 7\n5 2\n",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<bool> tham;\nvector<int> cha;\n\nvoid dfs(int u) {\n    tham[u] = true;\n    cout << u << \" \";\n    for (int v : adj[u])\n        if (!tham[v]) {\n            cha[v] = u;\n            dfs(v);                    // đi sâu vào v; xong mới quay lại thử đỉnh kề tiếp theo của u\n        }\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    tham.assign(n + 1, false);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    cha.assign(n + 1, 0);\n    dfs(1);\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,mark:"tham",par:"cha",cur:["u","v"]},{type:"calls"}],py:{code:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ntham = [False] * (n + 1)\ncha = [0] * (n + 1)\nthu_tu = []\n\ndef dfs(u):\n    tham[u] = True\n    thu_tu.append(u)\n    for v in adj[u]:\n        if not tham[v]:\n            cha[v] = u\n            dfs(v)                     # đi sâu vào v; xong mới quay lại thử đỉnh kề tiếp theo của u\n\ndfs(1)\nprint(*thu_tu)"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<int>[] adj;\n    static bool[] tham;\n    static int[] cha;\n\n    static void Dfs(int u)\n    {\n        tham[u] = true;\n        Console.Write(u + \" \");\n        foreach (int v in adj[u])\n            if (!tham[v])\n            {\n                cha[v] = u;\n                Dfs(v);                    // đi sâu vào v; xong mới quay lại thử đỉnh kề tiếp theo của u\n            }\n    }\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        tham = new bool[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        cha = new int[n + 1];\n        Dfs(1);\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: DFS bằng ngăn xếp tự quản lý",input:"7 7\n1 2\n1 3\n2 4\n3 4\n4 5\n6 7\n5 2\n",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n#include <stack>\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<bool> tham(n + 1, false);\n    stack<int> st;\n    st.push(1);\n    while (!st.empty()) {\n        int u = st.top();\n        st.pop();\n        if (tham[u]) continue;         // có thể đã được đẩy nhiều lần\n        tham[u] = true;\n        cout << u << \" \";\n        for (int i = (int)adj[u].size() - 1; i >= 0; i--)   // đẩy ngược để lấy ra theo đúng thứ tự\n            if (!tham[adj[u][i]]) st.push(adj[u][i]);\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,mark:"tham",cur:["u"]},{type:"cont",of:"st"}],py:{code:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ntham = [False] * (n + 1)\nst = [1]\nthu_tu = []\nwhile st:\n    u = st.pop()\n    if tham[u]:                        # có thể đã được đẩy nhiều lần\n        continue\n    tham[u] = True\n    thu_tu.append(u)\n    for v in reversed(adj[u]):         # đẩy ngược để lấy ra theo đúng thứ tự\n        if not tham[v]:\n            st.append(v)\nprint(*thu_tu)"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<int>[] adj;\n    static bool[] tham;\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        tham = new bool[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        var st = new Stack<int>();\n        st.Push(1);\n        while (st.Count > 0)\n        {\n            int u = st.Pop();\n            if (tham[u]) continue;             // có thể đã được đẩy nhiều lần\n            tham[u] = true;\n            Console.Write(u + \" \");\n            for (int i = adj[u].Count - 1; i >= 0; i--)   // đẩy ngược để lấy ra theo đúng thứ tự\n                if (!tham[adj[u][i]]) st.Push(adj[u][i]);\n        }\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Đếm thành phần liên thông",input:"8 5\n1 2\n2 3\n4 5\n6 7\n7 4\n",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<bool> tham;\nvector<int> comp;\n\nvoid dfs(int u, int c) {\n    tham[u] = true;\n    comp[u] = c;                       // u thuộc thành phần số c\n    for (int v : adj[u])\n        if (!tham[v]) dfs(v, c);\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    tham.assign(n + 1, false);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    comp.assign(n + 1, 0);\n    int soTP = 0;\n    for (int u = 1; u <= n; u++)\n        if (!tham[u]) {\n            soTP++;\n            dfs(u, soTP);              // một lần gọi thăm trọn một thành phần\n        }\n    cout << soTP << \"\\n\";\n    for (int u = 1; u <= n; u++) cout << comp[u] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,mark:"tham",lab:"comp",cur:["u"]}],py:{code:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ntham = [False] * (n + 1)\ncomp = [0] * (n + 1)\n\ndef dfs(u, c):\n    tham[u] = True\n    comp[u] = c                        # u thuộc thành phần số c\n    for v in adj[u]:\n        if not tham[v]:\n            dfs(v, c)\n\nso_tp = 0\nfor u in range(1, n + 1):\n    if not tham[u]:\n        so_tp += 1\n        dfs(u, so_tp)                  # một lần gọi thăm trọn một thành phần\nprint(so_tp)\nprint(*comp[1:])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<int>[] adj;\n    static bool[] tham;\n    static int[] comp;\n\n    static void Dfs(int u, int c)\n    {\n        tham[u] = true;\n        comp[u] = c;                       // u thuộc thành phần số c\n        foreach (int v in adj[u])\n            if (!tham[v]) Dfs(v, c);\n    }\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        tham = new bool[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        comp = new int[n + 1];\n        int soTP = 0;\n        for (int u = 1; u <= n; u++)\n            if (!tham[u])\n            {\n                soTP++;\n                Dfs(u, soTP);                  // một lần gọi thăm trọn một thành phần\n            }\n        Console.WriteLine(soTP);\n        for (int u = 1; u <= n; u++) Console.Write(comp[u] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Đếm hòn đảo bằng tô loang",input:"",code:"#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvector<string> g = {\"##..#\",\n                    \"#...#\",\n                    \"..#..\",\n                    \"....#\"};\nint R = 4, C = 5;\nint nhan[4][5];\n\nvoid loang(int x, int y, int c) {\n    if (x < 0 || x >= R || y < 0 || y >= C) return;   // ra ngoài\n    if (g[x][y] != '#' || nhan[x][y] != 0) return;     // nước hoặc đã tô\n    nhan[x][y] = c;\n    loang(x - 1, y, c); loang(x + 1, y, c);\n    loang(x, y - 1, c); loang(x, y + 1, c);\n}\n\nint main() {\n    int dao = 0;\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++)\n            if (g[i][j] == '#' && nhan[i][j] == 0) loang(i, j, ++dao);\n    cout << dao << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"nhan"},{type:"calls"}],py:{code:"g = [\"##..#\",\n     \"#...#\",\n     \"..#..\",\n     \"....#\"]\nR, C = 4, 5\nnhan = [[0] * C for _ in range(R)]\n\ndef loang(x, y, c):\n    if not (0 <= x < R and 0 <= y < C):        # ra ngoài\n        return\n    if g[x][y] != \"#\" or nhan[x][y] != 0:      # nước hoặc đã tô\n        return\n    nhan[x][y] = c\n    loang(x - 1, y, c); loang(x + 1, y, c)\n    loang(x, y - 1, c); loang(x, y + 1, c)\n\ndao = 0\nfor i in range(R):\n    for j in range(C):\n        if g[i][j] == \"#\" and nhan[i][j] == 0:\n            dao += 1\n            loang(i, j, dao)\nprint(dao)"},cs:{code:"using System;\n\nclass Program\n{\n    static string[] g = { \"##..#\",\n                          \"#...#\",\n                          \"..#..\",\n                          \"....#\" };\n    static int R = 4, C = 5;\n    static int[][] nhan = { new int[5], new int[5], new int[5], new int[5] };\n\n    static void Loang(int x, int y, int c)\n    {\n        if (x < 0 || x >= R || y < 0 || y >= C) return;   // ra ngoài\n        if (g[x][y] != '#' || nhan[x][y] != 0) return;     // nước hoặc đã tô\n        nhan[x][y] = c;\n        Loang(x - 1, y, c); Loang(x + 1, y, c);\n        Loang(x, y - 1, c); Loang(x, y + 1, c);\n    }\n\n    static void Main()\n    {\n        int dao = 0;\n        for (int i = 0; i < R; i++)\n            for (int j = 0; j < C; j++)\n                if (g[i][j] == '#' && nhan[i][j] == 0) Loang(i, j, ++dao);\n        Console.WriteLine(dao);\n    }\n}"}},{label:"Lỗi: đệ quy quá sâu",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<bool> tham;\n\nint dem = 0;\n\nvoid dfs(int u) {\n    tham[u] = true;\n    dem++;\n    for (int v : adj[u])\n        if (!tham[v]) dfs(v);\n}\n\nint main() {\n    int n = 6000;                      // một con đường thẳng 1 - 2 - … - 6000\n    adj.resize(n + 1);\n    tham.assign(n + 1, false);\n    for (int u = 1; u < n; u++) { adj[u].push_back(u + 1); adj[u + 1].push_back(u); }\n    dfs(1);\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["u","dem"]}],py:{code:"n = 6000                               # một con đường thẳng 1 - 2 - … - 6000\nadj = [[] for _ in range(n + 1)]\nfor u in range(1, n):\n    adj[u].append(u + 1)\n    adj[u + 1].append(u)\ntham = [False] * (n + 1)\ndem = 0\n\ndef dfs(u):\n    global dem\n    tham[u] = True\n    dem += 1\n    for v in adj[u]:\n        if not tham[v]:\n            dfs(v)\n\ndfs(1)\nprint(dem)",note:"Python mặc định chỉ cho đệ quy khoảng 1000 tầng: RecursionError. sys.setrecursionlimit nâng được giới hạn nhưng vẫn có thể làm sập chương trình với đồ thị rất sâu. Cách chắc chắn: DFS bằng list làm ngăn xếp, hoặc BFS."},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 1000000, dem = 0;\n\n    static void Dfs(int u)\n    {\n        if (u > n) return;\n        dem++;\n        Dfs(u + 1);                        // lồng sâu thêm một tầng cho mỗi đỉnh\n    }\n\n    static void Main()\n    {\n        Dfs(1);                                // đồ thị là một đường 1 - 2 - … - n: từ u chỉ đi tiếp sang u + 1\n        Console.WriteLine(dem);\n    }\n}",note:"Đồ thị là một đường dài một triệu đỉnh nên Dfs lồng nhau một triệu tầng: trình mô phỏng dừng ngay khi vượt 5000 tầng, còn .NET thật dừng với Stack overflow (và không bắt được bằng try/catch). Dùng Stack<int> tự quản lý, hoặc BFS.",viz:[{type:"vars",names:["u","dem"]}]}}];
