makeEx2(document.getElementById("ex-l53"),sim53,[{t:"Các cụm đảo",d:"Có n hòn đảo và m cây cầu hai chiều (1 ≤ n ≤ 2·10^5, 0 ≤ m ≤ 2·10^5). Đầu vào: n m rồi m dòng u v. Đầu ra: hai số: số cụm (thành phần liên thông) và số đảo của cụm lớn nhất.",tests:[{in:"8 5\n1 2\n2 3\n4 5\n6 7\n7 4",out:"3 4"},{in:"3 0\n",out:"3 1"},{in:"4 4\n1 2\n2 3\n3 4\n4 1",out:"1 4"},{in:"5 2\n1 1\n2 2",out:"5 1"},{in:"40 25\n40 14\n30 33\n31 34\n24 30\n2 3\n11 23\n9 17\n4 11\n4 24\n15 29\n13 15\n9 23\n33 21\n33 26\n4 22\n18 10\n6 36\n27 25\n29 16\n10 4\n29 31\n15 23\n38 15\n10 6\n3 7",out:"15 22"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<bool> tham;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    tham.assign(n + 1, false);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    int soCum = 0, lonNhat = 0;\n    // với mỗi đỉnh chưa thăm: duyệt cả thành phần của nó, đếm số đỉnh\n    cout << soCum << \" \" << lonNhat << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=n-1;i>=1;i--)if(i%50)r.push((i+1)+" "+i);return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"n",limit:n=>80*n+300,why:"Gán nhãn bằng cách lặp lại việc lan nhãn qua mọi cạnh tới khi không đổi tốn O(n·m)."},py:{start:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ntham = [False] * (n + 1)\nso_cum, lon_nhat = 0, 0\n# với mỗi đỉnh chưa thăm: duyệt cả thành phần của nó (dùng list làm ngăn xếp), đếm số đỉnh\nprint(so_cum, lon_nhat)",hints:["Duyệt s = 1 … n; gặp đỉnh chưa thăm thì đó là một cụm mới: tăng bộ đếm, rồi duyệt cả cụm từ s.","Dùng list làm ngăn xếp (append/pop) thay cho đệ quy: Python giới hạn độ sâu đệ quy khoảng 1000.","Đánh dấu khi đẩy vào để mỗi đỉnh vào ngăn xếp đúng một lần; đếm số đỉnh lấy ra."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<int>[] adj;\n    static bool[] tham;\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        tham = new bool[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        int soCum = 0, lonNhat = 0;\n        // với mỗi đỉnh chưa thăm: duyệt cả thành phần của nó (Stack<int>), đếm số đỉnh\n        Console.WriteLine(soCum + \" \" + lonNhat);\n    }\n}",hints:["Duyệt s = 1 … n; gặp đỉnh chưa thăm thì đó là một cụm mới: tăng bộ đếm, rồi duyệt cả cụm từ s.","Dùng Stack<int> thay cho đệ quy để không lo tràn ngăn xếp với đồ thị dài.","Đánh dấu khi đẩy vào để mỗi đỉnh vào ngăn xếp đúng một lần; đếm số đỉnh lấy ra."]}},{t:"Đếm hòn đảo",d:"Bản đồ R × C (1 ≤ R, C ≤ 1000): '#' là đất, '.' là nước. Các ô đất chung cạnh thuộc cùng một hòn đảo. Đầu vào: R C rồi R dòng. Đầu ra: số hòn đảo.",tests:[{in:"4 5\n##..#\n#...#\n..#..\n....#",out:"4"},{in:"1 1\n.",out:"0"},{in:"1 1\n#",out:"1"},{in:"3 3\n#.#\n.#.\n#.#",out:"5"},{in:"3 3\n###\n#.#\n###",out:"1"},{in:"20 30\n.#.#####.#......###.####.#.###\n...#..##.###.#...##.#.....#..#\n#.#..#.....#.##.#.####.#......\n...##..#..#.#..###.#..###..##.\n....#....#..#.##..##....#.###.\n..#..###.####.###..####..#...#\n.###..#..#.##...######.#.#....\n.####.##...###...##....##.#.#.\n##.........##.#.#...##..##.#.#\n..#...#.#.#..#.#..#####.#..##.\n......##........#....###...#..\n.##.#.#..###...####.#.####..##\n#...#.#.#....####....#.#..#...\n#.#.#..###.##.####.#.#.......#\n##...#...##..#....#...#..#..#.\n##..#...####.####...##....#.##\n..#..##...#...####...#..#..#..\n#....#...#.#..#..#..#..##....#\n.#.#.#.#.##.....#.#....#.#.#..\n..#...#...#####...##.##.#.#.#.",out:"80"}],start:"#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint R, C;\nvector<string> g;\nvector<vector<bool>> tham;\n\nint main() {\n    cin >> R >> C;\n    g.resize(R);\n    for (int i = 0; i < R; i++) cin >> g[i];\n    tham.assign(R, vector<bool>(C, false));\n    int dao = 0;\n    // mỗi ô đất chưa thăm là một đảo mới: tô loang cả đảo\n    cout << dao << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const C=Math.floor(n/4);const r=["#".repeat(C),".".repeat(C-1)+"#","#".repeat(C),"#"+".".repeat(C-1)];return "4 "+C+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"n",limit:n=>150*n+300,why:"Lan nhãn lặp đi lặp lại trên cả lưới tới khi ổn định tốn O((R·C)²)."},py:{start:"R, C = map(int, input().split())\ng = [input() for _ in range(R)]\ntham = [[False] * C for _ in range(R)]\ndao = 0\n# mỗi ô đất chưa thăm là một đảo mới: tô loang cả đảo\nprint(dao)",hints:["Duyệt mọi ô; gặp ô đất chưa thăm thì tăng số đảo và tô loang toàn bộ đảo đó.","Chỉ đi sang ô chung cạnh (4 hướng). Kiểm tra biên trước khi đọc g[nx][ny].","Đảo có thể rất dài: dùng list làm ngăn xếp thay cho đệ quy."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] rc = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int R = rc[0], C = rc[1];\n        string[] g = new string[R];\n        for (int i = 0; i < R; i++) g[i] = Console.ReadLine();\n        bool[] tham = new bool[R * C];         // ô (x, y) ứng với chỉ số x * C + y\n        int dao = 0;\n        // mỗi ô đất chưa thăm là một đảo mới: tô loang cả đảo\n        Console.WriteLine(dao);\n    }\n}",hints:["Duyệt mọi ô; gặp ô đất chưa thăm thì tăng số đảo và tô loang toàn bộ đảo đó.","Cất ô (x, y) thành x · C + y để dùng Stack<int> và mảng một chiều.","Đảo có thể rất dài: dùng ngăn xếp tự quản lý thay cho đệ quy."]}},{t:"Lan truyền tin đồn",d:"Mạng có n người, m quan hệ một chiều: u v nghĩa là u nghe được tin thì kể cho v. Người 1 biết tin đầu tiên. Đầu vào: n m (1 ≤ n, m ≤ 2·10^5) rồi m dòng u v. Đầu ra: dòng 1 là số người cuối cùng biết tin (tính cả người 1); dòng 2 là danh sách những người đó, tăng dần.",tests:[{in:"5 4\n1 2\n2 3\n4 1\n3 1",out:"3\n1 2 3"},{in:"3 2\n2 1\n3 1",out:"1\n1"},{in:"4 3\n1 2\n1 3\n1 4",out:"4\n1 2 3 4"},{in:"6 5\n1 2\n2 3\n3 4\n5 6\n4 2",out:"4\n1 2 3 4"},{in:"30 35\n23 27\n24 2\n1 14\n27 10\n19 23\n19 7\n20 1\n17 20\n16 17\n5 22\n16 8\n15 29\n20 14\n25 1\n4 13\n2 11\n2 17\n20 19\n13 6\n24 26\n25 4\n10 22\n5 12\n28 30\n21 25\n15 17\n15 16\n7 19\n28 20\n25 14\n2 20\n3 7\n17 1\n16 30\n5 11",out:"2\n1 14"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);           // có hướng\n    }\n    vector<bool> tham(n + 1, false);\n    // duyệt từ đỉnh 1 theo chiều cạnh; rồi in các đỉnh đã thăm theo thứ tự 1..n\n    cout << 0 << \"\\n\" << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=n-1;i>=1;i--)r.push(i+" "+(i+1));for(let i=3;i<=n;i+=3)r.push(i+" "+(i-2));return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"n",limit:n=>80*n+300,why:"Lặp lại việc lan dấu “biết tin” qua mọi cạnh tới khi không đổi tốn O(n·m)."},py:{start:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)                   # có hướng\ntham = [False] * (n + 1)\n# duyệt từ đỉnh 1 theo chiều cạnh; rồi in các đỉnh đã thăm theo thứ tự 1..n\nprint(0)\nprint()",hints:["Đồ thị có hướng: chỉ adj[u].append(v).","Duyệt từ đỉnh 1 (list làm ngăn xếp, hoặc deque cho BFS); mọi đỉnh được thăm là người biết tin.","Không cần sắp xếp: lấy các u từ 1 tới n mà tham[u] đúng là đã tăng dần."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);               // có hướng\n        }\n        bool[] tham = new bool[n + 1];\n        // duyệt từ đỉnh 1 theo chiều cạnh; rồi in các đỉnh đã thăm theo thứ tự 1..n\n        Console.WriteLine(0);\n        Console.WriteLine();\n    }\n}",hints:["Đồ thị có hướng: chỉ adj[u].Add(v).","Duyệt từ đỉnh 1 (Stack hoặc Queue); mọi đỉnh được thăm là người biết tin.","Không cần sắp xếp: in các u từ 1 tới n mà tham[u] đúng là đã tăng dần."]}}]);

